extension WarningControlRegionNode: Comparable {
  static func == (lhs: WarningControlRegionNode, rhs: WarningControlRegionNode) -> Bool {
    return lhs.range == rhs.range
  }

  static func < (lhs: WarningControlRegionNode, rhs: WarningControlRegionNode) -> Bool {
    if lhs.range.lowerBound != rhs.range.lowerBound {
      return lhs.range.lowerBound < rhs.range.lowerBound
    }
    // For same start, larger interval comes first (reverse order by end)
    // This can happen, for example, when the top-level region (source-file scope)
    // also contains a warning control scope at the very beginning which
    // also begins at position 0.
    return lhs.range.upperBound > .range.upperBound
  }
}
extension SyntaxProtocol {
  /// Check whether the non-type erased version of this syntax node conforms to
  /// `WithCodeBlockSyntax`.
  /// Note that this will incur an existential conversion.
  public func isProtocol(_:WithCodeBlockSyntax.Protocol) -> Bool {
    return self.asProtocol(WithCodeBlockSyntax.self) != nil
  }

  /// Return the non-type erased version of this syntax node if it conforms to
  /// `WithCodeBlockSyntax`. Otherwise return `nil`.
  /// Note that this will incur an existential conversion.
  public func asProtocol(_: WithCodeBlockSyntax.Protocol) -> WithCodeBlockSyntax? {
    return Syntax(self).asProtocol(SyntaxProtocol.self) as? WithCodeBlockSyntax
  }
}
}

